{
  "user_intent": "Create a regular hexagon nut: 30mm across flats, 8mm thick, 10mm diameter through hole at center, centered on origin in thickness direction.",
  "steps": [
    {
      "operation": "new_part",
      "params": {}
    },
    {
      "operation": "select_plane",
      "params": {
        "index": 0
      }
    },
    {
      "operation": "sketch_polygon",
      "params": {
        "cx": 0.0,
        "cy": 0.0,
        "circumradius": 0.017321,
        "sides": 6,
        "startAngleDeg": 0
      }
    },
    {
      "operation": "sketch_circle",
      "params": {
        "cx": 0.0,
        "cy": 0.0,
        "radius": 0.005
      }
    },
    {
      "operation": "feature_extrusion",
      "params": {
        "depth": 0.008,
        "midPlane": true
      }
    }
  ],
  "notes": "Regular hexagon nut: across-flats=30mm → circumradius=30/√3≈17.321mm. The 10mm-diameter circle (r=5mm) is nested inside the hexagon in the same sketch, so the single extrusion automatically produces the through hole. midPlane=true centers the 8mm thickness symmetrically about the front plane (origin in Z). No separate cut_extrusion needed."
}

